import React, { useEffect, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { Icon } from '../../components/Icon';
import { SectionTitle } from '../../components/ui';
import { useT } from '../../i18n';
import { engine } from '../../services/engine';
import { useTheme } from '../../theme/useTheme';
import { spacing } from '../../theme/themes';

/** Previews of the launcher icon variants generated by scripts/generate-app-icons.py. */
export const APP_ICONS: { id: string; background: string; glyph: string }[] = [
  { id: 'default', background: '#9333EA', glyph: '#FFFFFF' },
  { id: 'blue', background: '#3B82F6', glyph: '#FFFFFF' },
  { id: 'teal', background: '#14B8A6', glyph: '#FFFFFF' },
  { id: 'green', background: '#22C55E', glyph: '#FFFFFF' },
  { id: 'orange', background: '#F97316', glyph: '#FFFFFF' },
  { id: 'rose', background: '#F43F5E', glyph: '#FFFFFF' },
  { id: 'midnight', background: '#1D1830', glyph: '#A855F7' },
  { id: 'cream', background: '#FFF1F4', glyph: '#C2577F' },
];

export function AppIconPicker() {
  const theme = useTheme();
  const t = useT();
  const [current, setCurrent] = useState<string | null>(null);

  useEffect(() => {
    engine.getAppIcon().then(setCurrent);
  }, []);

  const choose = async (id: string) => {
    setCurrent(id);
    await engine
      .setAppIcon(id)
      .catch(() => engine.getAppIcon().then(setCurrent));
  };

  return (
    <>
      <SectionTitle>{t('appIcon')}</SectionTitle>
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.row}
      >
        {APP_ICONS.map(icon => {
          const selected = current === icon.id;
          return (
            <Pressable
              key={icon.id}
              testID={`app-icon-${icon.id}`}
              onPress={() => choose(icon.id)}
              accessibilityRole="radio"
              accessibilityState={{ checked: selected }}
              accessibilityLabel={icon.id}
              style={[
                styles.ring,
                selected ? { borderColor: theme.colors.text } : styles.ringOff,
              ]}
            >
              <View style={[styles.icon, { backgroundColor: icon.background }]}>
                <Icon
                  name="alarm"
                  color={icon.glyph}
                  size={30}
                  strokeWidth={2.4}
                />
              </View>
            </Pressable>
          );
        })}
      </ScrollView>
      <Text style={[styles.hint, { color: theme.colors.textSecondary }]}>
        {t('appIconHint')}
      </Text>
    </>
  );
}

const styles = StyleSheet.create({
  row: { gap: spacing.sm, paddingHorizontal: spacing.xs },
  ring: { padding: 3, borderRadius: 20, borderWidth: 2 },
  ringOff: { borderColor: 'transparent' },
  icon: {
    width: 52,
    height: 52,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  hint: { fontSize: 13, marginTop: spacing.sm, marginHorizontal: spacing.xs },
});
